@system(id: "recipes.audio")
class AudioSystem {
    @query(Cues) var games;
    @query(AudioSource, CueName) var sounds;

    func update(context) {
        var hit = false;
        for (var game in games) {
            hit = game.cues.hit;
            game.cues.hit = false;
